-- Candidate migration for a NEW, isolated database; do not run against existing sites.
CREATE TABLE users (id VARCHAR(32) PRIMARY KEY, email VARCHAR(254) NOT NULL UNIQUE, email_verified_at BIGINT NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE auth_challenges (id VARCHAR(32) PRIMARY KEY, email VARCHAR(254) NOT NULL, code_hash CHAR(64) NOT NULL, binding_hash CHAR(64) NOT NULL, requester_hash CHAR(64) NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, attempts INT NOT NULL DEFAULT 0, used_at BIGINT NULL, INDEX challenge_email_time(email,created_at), INDEX challenge_requester_time(requester_hash,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE auth_quotas (bucket_hash CHAR(64) PRIMARY KEY, window_start BIGINT NOT NULL, hits INT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id VARCHAR(32) NOT NULL, csrf_hash CHAR(64) NOT NULL, created_at BIGINT NOT NULL, expires_at BIGINT NOT NULL, revoked_at BIGINT NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE email_outbox (id VARCHAR(32) PRIMARY KEY, idempotency_key VARCHAR(100) NOT NULL UNIQUE, payload_sealed TEXT NOT NULL, status VARCHAR(20) NOT NULL, created_at BIGINT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE purchase_sources (transaction_id VARCHAR(80) PRIMARY KEY, email VARCHAR(254) NOT NULL, product_id VARCHAR(80) NOT NULL, offer_code VARCHAR(80) NOT NULL, state_json LONGTEXT NOT NULL, revision BIGINT NOT NULL DEFAULT 0, quarantine_reason VARCHAR(100) NULL, INDEX purchase_owner(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE purchase_events (event_id VARCHAR(80) PRIMARY KEY, payload_hash CHAR(64) NOT NULL, transaction_id VARCHAR(80) NOT NULL, disposition VARCHAR(30) NOT NULL, received_at BIGINT NOT NULL, FOREIGN KEY(transaction_id) REFERENCES purchase_sources(transaction_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE protected_objects (id VARCHAR(80) PRIMARY KEY, storage_key VARCHAR(180) NOT NULL UNIQUE, provider VARCHAR(30) NOT NULL, mime VARCHAR(80) NOT NULL, required_scopes_json TEXT NOT NULL, visibility VARCHAR(20) NOT NULL, owner_id VARCHAR(32) NULL, status VARCHAR(20) NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE object_teacher_access (object_id VARCHAR(80) NOT NULL, user_id VARCHAR(32) NOT NULL, PRIMARY KEY(object_id,user_id), FOREIGN KEY(object_id) REFERENCES protected_objects(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE user_state (user_id VARCHAR(32) NOT NULL, area VARCHAR(80) NOT NULL, revision BIGINT NOT NULL, data_json LONGTEXT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY(user_id,area), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
